from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def summary_ranges(nums: list[int]) -> list[str]:
    if not nums:
        return []
    out: list[str] = []
    start = prev = nums[0]
    for value in nums[1:]:
        if value == prev + 1:
            prev = value
        else:
            out.append(str(start) if start == prev else f"{start}->{prev}")
            start = prev = value
    out.append(str(start) if start == prev else f"{start}->{prev}")
    return out

